import React, { Component } from 'react';
import { Card, Table, Icon, Button, Spin, Alert, Input, Dropdown, Menu, Modal, message, Tag } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';

const { Search } = Input;

class DataSetsList extends Component {
    constructor(props) {
        super(props);
        this.state = {
            dataSets: [], // All data sets
            loading: false,
            error: null,
            searchValue: '',
            filteredDataSets: [],
            deletingDataSetId: null // Track which data set is being deleted
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchDataSets();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchDataSets = async () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('dataSets', {
                filter: 'name:ne:default',
                fields: 'displayName,shortName,id,lastUpdated,created,displayDescription,code,sharing,access,href,level,displayName,formType,periodType,publicAccess,lastUpdated',
                order: 'displayName:ASC',
                paging: false
            });
            
            if (this._isMounted) {
                this.setState({
                    dataSets: data.dataSets || [],
                    filteredDataSets: data.dataSets || [],
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching data sets:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch data sets. Please try again.',
                    loading: false
                });
            }
        }
    };

    handleDataSetClick = (dataSet) => {
        const redirectUrl = `/sims-web-maintenance/#/edit/dataSetSection/dataSet/${dataSet.id}`;
        window.location.href = redirectUrl;
    };

    handleManageSectionsClick = (dataSet) => {
        const redirectUrl = `/sims-web-maintenance/#/edit/dataSetSection/dataSet/${dataSet.id}/sections`;
        window.location.href = redirectUrl;
    };

    handleDesignFormClick = (dataSet) => {
        const redirectUrl = `/sims-web-maintenance/#/edit/dataSetSection/dataSet/${dataSet.id}/dataEntryForm`;
        window.location.href = redirectUrl;
    };

    handleDataSetDelete = (dataSet) => {
        Modal.confirm({
            title: 'Delete Data Set',
            content: (
                <div>
                    <p>Are you sure you want to delete the data set <strong>"{dataSet.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteDataSet(dataSet.id);
            },
        });
    };

    deleteDataSet = async (dataSetId) => {
        this.setState({ deletingDataSetId: dataSetId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            await api.delete(`dataSets/${dataSetId}`);

            // Remove the deleted data set from state
            const updatedDataSets = this.state.dataSets.filter(dataSet => dataSet.id !== dataSetId);
            const updatedFilteredDataSets = this.state.filteredDataSets.filter(dataSet => dataSet.id !== dataSetId);

            this.setState({
                dataSets: updatedDataSets,
                filteredDataSets: updatedFilteredDataSets,
                deletingDataSetId: null
            });

            message.success('Data set deleted successfully');
        } catch (error) {
            console.error('Error deleting data set:', error);
            this.setState({ deletingDataSetId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the data set: ${error.message}`,
            });
        }
    };

    handleCreateDataSet = () => {
        // Navigate to create new data set page
        const redirectUrl = `/sims-web-maintenance/#/edit/dataSetSection/dataSet/add`;
        window.location.href = redirectUrl;
    };

    // Get more actions menu for data sets
    getDataSetActionsMenu = (dataSet) => {
        const { deletingDataSetId } = this.state;
        const isDeleting = deletingDataSetId === dataSet.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleDataSetClick(dataSet)}>
                    <Icon type="edit" style={{ marginRight: 8 }} />
                    Edit Data Set details
                </Menu.Item>
                <Menu.Item key="manage-sections" onClick={() => this.handleManageSectionsClick(dataSet)}>
                    <Icon type="profile" style={{ marginRight: 8 }} />
                    Manage Sections
                </Menu.Item>
                <Menu.Item key="design" onClick={() => this.handleDesignFormClick(dataSet)}>
                    <Icon type="form" style={{ marginRight: 8 }} />
                    Design Data Entry Form
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleDataSetDelete(dataSet)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Data Set'}
                </Menu.Item>
            </Menu>
        );
    };

    handleSearch = (value) => {
        const { dataSets } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredDataSets: dataSets
            });
            return;
        }

        const searchTerm = value.toLowerCase();
        const filteredDataSets = dataSets.filter(dataSet => {
            // Search in data set name, ID, code, short name, and description
            const dataSetMatches = dataSet.displayName.toLowerCase().includes(searchTerm) ||
                dataSet.id.toLowerCase().includes(searchTerm) ||
                (dataSet.code && dataSet.code.toLowerCase().includes(searchTerm)) ||
                (dataSet.shortName && dataSet.shortName.toLowerCase().includes(searchTerm)) ||
                (dataSet.displayDescription && dataSet.displayDescription.toLowerCase().includes(searchTerm)) ||
                (dataSet.periodType && dataSet.periodType.toLowerCase().includes(searchTerm));

            return dataSetMatches;
        });

        this.setState({
            searchValue: value,
            filteredDataSets: filteredDataSets
        });
    };

    formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        const date = new Date(dateString);
        return date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    };

    render() {
        const { dataSets, loading, error, searchValue, filteredDataSets } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '1400px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading data sets...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchDataSets}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        const columns = [
            {
                title: 'Data Set Name',
                dataIndex: 'displayName',
                key: 'displayName',
                width: 300,
                render: (text, dataSet) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon
                                type="table"
                                style={{
                                    color: '#1890ff',
                                    marginRight: '8px'
                                }}
                            />
                            <div>
                                <div
                                    style={{ fontWeight: '500' }}
                                    dangerouslySetInnerHTML={{ __html: displayText }}
                                />
                                {dataSet.shortName && (
                                    <div style={{ fontSize: '12px', color: '#666', marginTop: '2px' }}>
                                        {dataSet.shortName}
                                    </div>
                                )}
                            </div>
                        </div>
                    );
                }
            },
            {
                title: 'Period Type',
                dataIndex: 'periodType',
                key: 'periodType',
                width: 120,
                render: (text) => {
                    const colorMap = {
                        'Monthly': '#52c41a',
                        'Yearly': '#1890ff',
                        'Quarterly': '#fa8c16',
                        'Weekly': '#722ed1',
                        'Daily': '#13c2c2'
                    };

                    return (
                        <Tag color={colorMap[text] || '#666'} style={{ fontSize: '11px' }}>
                            {text || 'N/A'}
                        </Tag>
                    );
                }
            },
            {
                title: 'Form Type',
                dataIndex: 'formType',
                key: 'formType',
                width: 120,
                render: (text) => {
                    const formTypeMap = {
                        'DEFAULT': 'Default Form',
                        'SECTION': 'Section Form',
                        'CUSTOM': 'Custom Form'
                    };

                    return (
                        <p>
                            {formTypeMap[text] || text || 'Default'}
                        </p>
                    );
                }
            },
            {
                title: 'Last Updated',
                dataIndex: 'lastUpdated',
                key: 'lastUpdated',
                width: 150,
                render: (text) => (
                    <span style={{ fontSize: '12px', color: '#666' }}>
                        {this.formatDate(text)}
                    </span>
                )
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                fixed: 'right',
                render: (text, dataSet) => (
                    <Dropdown
                        overlay={this.getDataSetActionsMenu(dataSet)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        const dataSource = searchValue ? filteredDataSets : dataSets;

        return (
            <div style={{ position: 'relative' }}>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Data Sets
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Manage and view all data sets in the system
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Table Content */}
                    <div style={{ padding: '0 24px 24px 24px' }}>
                        {dataSets.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '60px 0', color: '#999' }}>
                                <Icon type="table" style={{ fontSize: '64px', color: '#d9d9d9', marginBottom: '16px' }} />
                                <div style={{ fontSize: '16px' }}>No data sets found</div>
                            </div>
                        ) : (
                            <div>
                                <Search
                                    placeholder="Search data sets by name, ID, code, period type, or description"
                                    value={searchValue}
                                    onChange={(e) => this.handleSearch(e.target.value)}
                                    style={{ width: 500, marginBottom: 16 }}
                                />
                                {searchValue && (
                                    <div style={{ marginBottom: 16, color: '#666', fontSize: '14px' }}>
                                        <Icon type="search" style={{ marginRight: '4px' }} />
                                        Found {dataSource.length} data set(s) for "{searchValue}"
                                    </div>
                                )}
                                <Table
                                    columns={columns}
                                    dataSource={dataSource}
                                    rowKey="id"
                                    scroll={{ x: 1200 }}
                                    pagination={{
                                        pageSize: 10,
                                        showSizeChanger: true,
                                        showQuickJumper: true,
                                        showTotal: (total, range) =>
                                            `${range[0]}-${range[1]} of ${total} ${searchValue ? 'filtered' : ''} data sets`,
                                    }}
                                    size="middle"
                                />
                            </div>
                        )}
                    </div>
                </Card>

                {/* Floating Add Button */}
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    zIndex: 1000
                }}>
                    <Button
                        type="primary"
                        size="large"
                        shape="circle"
                        icon="plus"
                        onClick={this.handleCreateDataSet}
                        style={{
                            width: '56px',
                            height: '56px',
                            fontSize: '20px',
                            boxShadow: '0 4px 12px rgba(24, 144, 255, 0.3)',
                            border: 'none'
                        }}
                        title="Add New Data Set"
                    />
                </div>
            </div>
        );
    }
}

DataSetsList.contextTypes = {
    d2: PropTypes.object
};

export default DataSetsList;



